add(s,'a0','code (Operation-Code) and zero or more Operands.','کوڈ (آپریشن کوڈ) اور صفر یا زیادہ آپرینڈز شامل ہونے چاہئیں۔','کوډ (د عملیاتو کوډ) او صفر یا ډیر عملوندونه شامل وي.',cont=True)
G(s,'Instruction register','ہدایتی رجسٹر','د لارښوونې رجستر','Instruction register is a part of Control Unit, which stores the instructions currently being executed.','ہدایتی رجسٹر کنٹرول یونٹ کا حصہ ہے جو فی الوقت چلائی جانے والی ہدایات کو محفوظ کرتا ہے۔','د لارښوونې رجستر د کنټرول واحد یوه برخه ده چې اوس مهال اجرا کېدونکې لارښوونې ساتي.')
G(s,'Internet Protocol address (IP address)','انٹرنیٹ پروٹوکول ایڈریس (آئی پی ایڈریس)','د انټرنېټ پروتوکول پته (IP پته)','An Internet Protocol address (IP address) is a number that is used to identify a device, for example a computer, a printer, on the network.','انٹرنیٹ پروٹوکول ایڈریس (آئی پی ایڈریس) ایک نمبر ہے جو نیٹ ورک پر کسی آلے، مثلاً کمپیوٹر، پرنٹر، کی شناخت کے لیے استعمال ہوتا ہے۔','د انټرنېټ پروتوکول پته (IP پته) یوه شمېره ده چې په شبکه د یوې وسیلې، د بېلګې په توګه کمپیوټر، پرنټر، د پېژندلو لپاره کارول کېږي.')
LT(s,'K','ک','ک')
G(s,'Key','کی','کیلي','Key is a unique identifier which is required to track and analyze data effectively.','کی ایک منفرد شناخت کنندہ ہے جو ڈیٹا کو مؤثر طریقے سے ٹریک اور تجزیہ کرنے کے لیے درکار ہوتا ہے۔','کیلي یو ځانګړی پېژندونکی دی چې د ډېټا د اغېزمن تعقیب او تحلیل لپاره اړین دی.')
LT(s,'L','ل','ل')
G(s,'LAN (Local Area Network)','لین (لوکل ایریا نیٹ ورک)','LAN (ځایي سیمه شبکه)','LAN (Local Area Network) is a network that connects computers and devices in a limited geographical area like home, school, and office building, etc.','لین (لوکل ایریا نیٹ ورک) وہ نیٹ ورک ہے جو محدود جغرافیائی علاقے جیسے گھر، اسکول اور دفتر کی عمارت وغیرہ میں کمپیوٹرز اور آلات کو جوڑتا ہے۔','LAN (ځایي سیمه شبکه) هغه شبکه ده چې په محدوده جغرافیايي سیمه لکه کور، ښوونځي او د دفتر په ودانۍ او نورو کې کمپیوټرونه او وسایل نښلوي.')
G(s,'Language processor','لینگویج پراسیسر','د ژبې پروسیسر','Language processor or translator is a type of system software that translates a source program (other than machine language) into object program (Machine language).','لینگویج پراسیسر یا مترجم سسٹم سافٹ ویئر کی ایک قسم ہے جو ماخذ پروگرام (مشین لینگویج کے علاوہ) کو آبجیکٹ پروگرام (مشین لینگویج) میں ترجمہ کرتا ہے۔','د ژبې پروسیسر یا ژباړن د سیسټم سافټویر یو ډول دی چې د سرچینې پروګرام (له ماشین ژبې پرته) د څیز پروګرام (ماشین ژبې) ته ژباړي.')
G(s,'Licensed or Proprietary Software','لائسنس یافتہ یا ملکیتی سافٹ ویئر','جواز لرونکی یا ملکیتي سافټویر','Licensed or Proprietary Software is a computer software that is licensed, giving the right to use the software under certain conditions, but restricted from other uses, such as modification, further distribution and re-building under exclusive legal right of the copyright holder.','لائسنس یافتہ یا ملکیتی سافٹ ویئر کمپیوٹر سافٹ ویئر ہے جس کا لائسنس دیا گیا ہو، جو کچھ شرائط کے تحت سافٹ ویئر استعمال کرنے کا حق دیتا ہے لیکن دیگر استعمالات، جیسے ترمیم، مزید تقسیم اور دوبارہ تعمیر، کاپی رائٹ ہولڈر کے خصوصی قانونی حق کے تحت محدود ہوتے ہیں۔','جواز لرونکی یا ملکیتي سافټویر یو کمپیوټر سافټویر دی چې جواز لري، د ځینو شرطونو لاندې د سافټویر د کارولو حق ورکوي خو نورې کارونې، لکه تعدیل، نور وېش او بیا جوړول، د کاپي رایټ لرونکي ځانګړي قانوني حق لاندې محدودې دي.')
G(s,'Line of Sight communication','خطِ نظر مواصلات','د لیدو کرښې اړیکې','Line of Sight communication is a type of wireless data transfer that requires “visual contact” with the two devices/antennas.','خطِ نظر مواصلات وائرلیس ڈیٹا منتقلی کی ایک قسم ہے جس میں دو آلات/اینٹینا کے ساتھ ’’بصری رابطہ‘‘ درکار ہوتا ہے۔','د لیدو کرښې اړیکې د بې سیمې ډېټا د لېږد یو ډول دی چې له دوو وسایلو/انتنونو سره “لیدنیز اړیکې” ته اړتیا لري.')
G(s,'Low Earth Orbit (LEO)','لو ارتھ آربٹ (ایل ای او)','ټیټ ځمکنی مدار (LEO)','Low Earth Orbit (LEO) satellite operates at heights of between 500 and 2,000 km above the Earth’s surface.','لو ارتھ آربٹ (ایل ای او) سیٹلائٹ زمین کی سطح سے ۵۰۰ اور ۲،۰۰۰ کلومیٹر کے درمیان بلندیوں پر کام کرتا ہے۔','د ټیټ ځمکني مدار (LEO) سپوږمکۍ د ځمکې د مخ نه د ۵۰۰ او ۲،۰۰۰ کیلومترو ترمنځ لوړوالو کې کار کوي.')
LT(s,'M','م','م')
G(s,'Magnetic core memory','میگنیٹک کور میموری','مقناطیسي کور حافظه','Magnetic core memory was the most widely used form of digital computer memory based on a very simple idea. A core, a ring of magnetic material, stores one bit by the direction of its magnetization. A magnetic core is a ring of ferrite material.','میگنیٹک کور میموری ڈیجیٹل کمپیوٹر میموری کی سب سے زیادہ استعمال ہونے والی شکل تھی جو ایک بہت سادہ خیال پر مبنی تھی۔ کور، مقناطیسی مواد کا ایک چھلا، اپنی مقناطیسیت کی سمت سے ایک بٹ ذخیرہ کرتا ہے۔ میگنیٹک کور فیرائٹ مواد کا چھلا ہے۔','مقناطیسي کور حافظه د ډیجیټل کمپیوټر حافظې تر ټولو ډیر کارېدونکې بڼه وه چې پر یوې ډیرې ساده مفکورې ولاړه وه. کور، د مقناطیسي موادو حلقه، د خپل مقناطیسي کېدو د لوري په واسطه یو بټ ساتي. مقناطیسي کور د فرایټ موادو یوه حلقه ده.')
G(s,'Magnetic Storage','میگنیٹک اسٹوریج','مقناطیسي ذخیره','Magnetic storage refers to the storage of data on a magnetized medium.','میگنیٹک اسٹوریج سے مراد مقناطیسی وسیلے پر ڈیٹا کا ذخیرہ ہے۔','مقناطیسي ذخیره د ډېټا ساتلو ته په مقناطیسي شوي منځګړي اشاره کوي.')
G(s,'Magnetic Tape','میگنیٹک ٹیپ','مقناطیسي ټیپ','Magnetic Tape is a sequential access storage device used for data collection, backup and archiving.','میگنیٹک ٹیپ ترتیب وار رسائی والا ذخیرہ آلہ ہے جو ڈیٹا جمع کرنے، بیک اپ اور آرکائیونگ کے لیے استعمال ہوتا ہے۔','مقناطیسي ټیپ یوه پرله پسې لاسرسي ذخیره وسیله ده چې د ډېټا د راټولولو، بیک اپ او ارشیف کولو لپاره کارول کېږي.')
F.done()
